import { ChangeDetectionStrategy, Component, input } from '@angular/core';

export interface AevkoChartSeries {
  readonly key: string;
  readonly label: string;
  readonly color?: string;
}

@Component({
  selector: 'aevko-chart',
  standalone: true,
  templateUrl: './chart.component.html',
  styleUrl: './chart.component.css',
  changeDetection: ChangeDetectionStrategy.OnPush,
  host: { role: 'figure', '[attr.aria-label]': 'label()' },
})
export class AevkoChart {
  readonly label = input.required<string>();
  readonly description = input('');
  readonly series = input<readonly AevkoChartSeries[]>([]);
}

:host {
  border: 1px solid var(--aevko-border, #e4e4e7);
  border-radius: var(--aevko-radius, 0);
  display: grid;
  gap: 1rem;
  padding: 1rem;
}
.heading {
  display: grid;
  gap: 0.25rem;
}
.heading span {
  color: var(--aevko-muted, #71717a);
}
.visual {
  min-height: 12rem;
  min-width: 0;
}
.legend {
  display: flex;
  flex-wrap: wrap;
  gap: 0.75rem 1rem;
  list-style: none;
  margin: 0;
  padding: 0;
}
.legend li {
  align-items: center;
  display: inline-flex;
  font-size: 0.8125rem;
  gap: 0.375rem;
}
.swatch {
  background: var(--aevko-foreground, #09090b);
  height: 0.625rem;
  width: 0.625rem;
}
.data:empty {
  display: none;
}
